{"title": "Health summary", "type": "vega", "aggs": [], "params": {"spec": "{
 "$schema": "https://vega.github.io/schema/vega/v5.json",
 "autosize": {
  "type": "fit",
  "contains": "padding"
 },
 "padding": 0,
 "data": [
  {
   "name": "latest",
   "url": {
    "%context%": true,
    "%timefield%": "@timestamp",
    "index": "dashboard-health-monitor*",
    "body": {
     "size": 0,
     "aggs": {
      "d": {
       "terms": {
        "field": "dashboard_title",
        "size": 100
       },
       "aggs": {
        "latest": {
         "top_hits": {
          "size": 1,
          "sort": [
           {
            "@timestamp": {
             "order": "desc"
            }
           }
          ],
          "_source": {
           "includes": [
            "load_status",
            "load_time_ms",
            "panels_not_ok",
            "panel_count",
            "panels_checked",
            "expected_data_panels",
            "@timestamp",
            "collector_run_id"
           ]
          }
         }
        }
       }
      }
     }
    }
   },
   "format": {
    "property": "aggregations.d.buckets"
   },
   "transform": [
    {
     "type": "formula",
     "as": "src",
     "expr": "datum.latest.hits.hits[0]._source"
    },
    {
     "type": "formula",
     "as": "name",
     "expr": "datum.key"
    },
    {
     "type": "formula",
     "as": "status",
     "expr": "datum.src.load_status"
    },
    {
     "type": "formula",
     "as": "ms",
     "expr": "datum.src.load_time_ms || 0"
    },
    {
     "type": "formula",
     "as": "nok",
     "expr": "datum.src.panels_not_ok || 0"
    },
    {
     "type": "formula",
     "as": "total",
     "expr": "datum.src.panel_count || datum.src.panels_checked || 0"
    },
    {
     "type": "formula",
     "as": "ts",
     "expr": "time(toDate(datum.src['@timestamp']))"
    },
    {
     "type": "formula",
     "as": "age_min",
     "expr": "(now() - datum.ts) / 60000"
    },
    {
     "type": "formula",
     "as": "share",
     "expr": "datum.total > 0 ? datum.nok / datum.total : 0"
    },
    {
     "type": "formula",
     "as": "state",
     "expr": "datum.share >= 0.5 ? 'Action' : (datum.nok > 0 ? 'Attention' : (datum.status === 'ok' ? 'Healthy' : 'Slow'))"
    },
    {
     "type": "formula",
     "as": "rank",
     "expr": "datum.state === 'Action' ? 0 : (datum.state === 'Attention' ? 1 : (datum.state === 'Slow' ? 2 : 3))"
    }
   ]
  },
  {
   "name": "kpi",
   "source": "latest",
   "transform": [
    {
     "type": "formula",
     "as": "is_action",
     "expr": "datum.state === 'Action' ? 1 : 0"
    },
    {
     "type": "formula",
     "as": "is_attention",
     "expr": "datum.state === 'Attention' ? 1 : 0"
    },
    {
     "type": "formula",
     "as": "is_slow",
     "expr": "datum.state === 'Slow' ? 1 : 0"
    },
    {
     "type": "formula",
     "as": "has_nok",
     "expr": "datum.nok > 0 ? 1 : 0"
    },
    {
     "type": "aggregate",
     "fields": [
      "is_action",
      "is_attention",
      "is_slow",
      "has_nok",
      "nok",
      "ts",
      "ms"
     ],
     "ops": [
      "sum",
      "sum",
      "sum",
      "sum",
      "sum",
      "max",
      "max"
     ],
     "as": [
      "action",
      "attention",
      "slow",
      "with_nok",
      "nok_total",
      "newest",
      "slowest"
     ]
    },
    {
     "type": "formula",
     "as": "n",
     "expr": "length(data('latest'))"
    },
    {
     "type": "formula",
     "as": "age",
     "expr": "(now() - datum.newest) / 60000"
    }
   ]
  }
 ],
 "marks": [
  {
   "type": "rect",
   "encode": {
    "update": {
     "x": {
      "signal": "0 * width / 6 + 4"
     },
     "y": {
      "value": 4
     },
     "width": {
      "signal": "2 * width / 6 - 8"
     },
     "height": {
      "signal": "height - 8"
     },
     "fill": {
      "value": "#F6F8FB"
     },
     "cornerRadius": {
      "value": 6
     },
     "stroke": {
      "value": "#D5DCE6"
     },
     "strokeWidth": {
      "value": 1
     }
    }
   }
  },
  {
   "type": "rect",
   "encode": {
    "update": {
     "x": {
      "signal": "0 * width / 6 + 4"
     },
     "y": {
      "value": 4
     },
     "width": {
      "signal": "2 * width / 6 - 8"
     },
     "height": {
      "value": 4
     },
     "fill": {
      "signal": "verdict_color"
     },
     "cornerRadius": {
      "value": 2
     }
    }
   }
  },
  {
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "signal": "0 * width / 6 + 4 + 16"
     },
     "y": {
      "value": 30
     },
     "text": {
      "value": "\ud83e\udded  Overall health"
     },
     "fill": {
