{"title": "Status by dashboard", "type": "vega", "aggs": [], "params": {"spec": "{
 "$schema": "https://vega.github.io/schema/vega/v5.json",
 "autosize": {
  "type": "fit",
  "contains": "padding"
 },
 "padding": 0,
 "data": [
  {
   "name": "latest",
   "url": {
    "%context%": true,
    "%timefield%": "@timestamp",
    "index": "dashboard-health-monitor*",
    "body": {
     "size": 0,
     "aggs": {
      "d": {
       "terms": {
        "field": "dashboard_title",
        "size": 100
       },
       "aggs": {
        "latest": {
         "top_hits": {
          "size": 1,
          "sort": [
           {
            "@timestamp": {
             "order": "desc"
            }
           }
          ],
          "_source": {
           "includes": [
            "load_status",
            "load_time_ms",
            "panels_not_ok",
            "panel_count",
            "panels_checked",
            "expected_data_panels",
            "@timestamp",
            "collector_run_id"
           ]
          }
         }
        }
       }
      }
     }
    }
   },
   "format": {
    "property": "aggregations.d.buckets"
   },
   "transform": [
    {
     "type": "formula",
     "as": "src",
     "expr": "datum.latest.hits.hits[0]._source"
    },
    {
     "type": "formula",
     "as": "name",
     "expr": "datum.key"
    },
    {
     "type": "formula",
     "as": "status",
     "expr": "datum.src.load_status"
    },
    {
     "type": "formula",
     "as": "ms",
     "expr": "datum.src.load_time_ms || 0"
    },
    {
     "type": "formula",
     "as": "nok",
     "expr": "datum.src.panels_not_ok || 0"
    },
    {
     "type": "formula",
     "as": "total",
     "expr": "datum.src.panel_count || datum.src.panels_checked || 0"
    },
    {
     "type": "formula",
     "as": "ts",
     "expr": "time(toDate(datum.src['@timestamp']))"
    },
    {
     "type": "formula",
     "as": "age_min",
     "expr": "(now() - datum.ts) / 60000"
    },
    {
     "type": "formula",
     "as": "share",
     "expr": "datum.total > 0 ? datum.nok / datum.total : 0"
    },
    {
     "type": "formula",
     "as": "state",
     "expr": "datum.share >= 0.5 ? 'Action' : (datum.nok > 0 ? 'Attention' : (datum.status === 'ok' ? 'Healthy' : 'Slow'))"
    },
    {
     "type": "formula",
     "as": "rank",
     "expr": "datum.state === 'Action' ? 0 : (datum.state === 'Attention' ? 1 : (datum.state === 'Slow' ? 2 : 3))"
    },
    {
     "type": "collect",
     "sort": {
      "field": [
       "rank",
       "ms"
      ],
      "order": [
       "ascending",
       "descending"
      ]
     }
    },
    {
     "type": "window",
     "ops": [
      "row_number"
     ],
     "as": [
      "idx"
     ]
    },
    {
     "type": "formula",
     "as": "col",
     "expr": "(datum.idx - 1) % ncols"
    },
    {
     "type": "formula",
     "as": "row",
     "expr": "floor((datum.idx - 1) / ncols)"
    },
    {
     "type": "formula",
     "as": "color",
     "expr": "datum.state === 'Action' ? '#D13B34' : (datum.state === 'Attention' ? '#D68A00' : (datum.state === 'Slow' ? '#6F5BD0' : '#1E9E6A'))"
    },
    {
     "type": "formula",
     "as": "detail",
     "expr": "format(datum.ms / 1000, '.1f') + ' s  \u00b7  ' + (datum.total - datum.nok) + '/' + datum.total + ' panels ok'"
    }
   ]
  }
 ],
 "marks": [
  {
   "type": "rect",
   "from": {
    "data": "latest"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "datum.col * cw + 4"
     },
     "y": {
      "signal": "datum.row * rh + 4"
     },
     "width": {
      "signal": "cw - 8"
     },
     "height": {
      "signal": "rh - 8"
     },
     "fill": {
      "value": "#F6F8FB"
     },
     "stroke": {
      "value": "#D5DCE6"
     },
     "cornerRadius": {
      "value": 6
     },
     "tooltip": {
      "signal": "{'Dashboard': datum.name, 'State': datum.state, 'Collector status': datum.status, 'Load time (s)': format(datum.ms / 1000, '.1f'), 'Panels not ok': datum.nok + ' of ' + datum.total}"
     }
    }
   }
  },
  {
   "type": "rect",
   "from": {
    "data": "latest"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "datum.col * cw + 4"
     },
     "y": {
      "signal": "datum.row * rh + 4"
     },
     "width": {
      "signal": "cw - 8"
     },
     "height": {
      "value": 4
     },
     "fill": {
      "field": "color"
     },
     "cornerRadius": {
      "value": 2
     }
    }
   }
  },
  {
   "type": "text",
   "from": {
    "data": "latest"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "datum.col * cw + 4 + 12"
     },
     "y": {
      "signal": "datum.row * rh + 4 + 30"
     },
     "text": {
      "field": "name"
     },
     "fill": {
      "value": "#1A2433"
     },
     "fontSize": {
      "value": 12
     },
     "fontWeight": {
      "value": "600"
     },
     "limit": {
      "signal": "cw - 32"
     }
    }
   }
  },
  {
   "type": "text",
   "from": {
    "data": "latest"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "datum.col * cw + 4 + 12"
     },
     "y": {
      "signal": "datum.row * rh + 4 + 52"
     },
     "text": {
      "field": "state"
     },
     "fill": {
      "field": "color"
     },
     "fontSize": {
      "value": 15
     },
     "fontWeight": {
      "value": "bold"
     }
    }
   }
  },
  {
   "type": "text",
   "from": {
    "data": "latest"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "datum.col * cw + 4 + 12"
     },
     "y": {
      "signal": "datum.row * rh + 4 + 69"
     },
     "text": {
      "field": "detail"
     },
     "fill": {
      "value": "#5A6B80"
     },
     "fontSize": {
      "value": 11
     },
     "limit": {
      "signal": "cw - 32"
     }
    }
   }
  }
 ],
 "signals": [
  {
   "name": "ncols",
   "update": "max(1, floor(width / 190))"
  },
  {
   "name": "cw",
   "update": "width / ncols"
  },
  {
   "name": "rh",
   "value": 88
  }
 ]
}"}}

