{"title": "Panel health by dashboard", "type": "vega", "aggs": [], "params": {"spec": "{
 "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
 "title": "Panel health by dashboard (share of panel results)",
 "config": {
  "view": {
   "stroke": null
  },
  "background": null,
  "axis": {
   "labelColor": "#5A6B80",
   "titleColor": "#5A6B80",
   "gridColor": "#D5DCE6",
   "domainColor": "#D5DCE6",
   "tickColor": "#D5DCE6",
   "labelFontSize": 11
  },
  "legend": {
   "labelColor": "#1A2433",
   "titleColor": "#5A6B80"
  },
  "title": {
   "color": "#1A2433",
   "fontSize": 13,
   "anchor": "start"
  }
 },
 "data": {
  "url": {
   "%context%": true,
   "%timefield%": "@timestamp",
   "index": "dashboard-health-monitor*",
   "body": {
    "size": 0,
    "aggs": {
     "by_dash": {
      "terms": {
       "field": "dashboard_title",
       "size": 100,
       "order": {
        "_key": "asc"
       }
      },
      "aggs": {
       "ok": {
        "nested": {
         "path": "panels"
        },
        "aggs": {
         "f": {
          "filter": {
           "term": {
            "panels.render_status": "ok"
           }
          }
         }
        }
       },
       "empty": {
        "nested": {
         "path": "panels"
        },
        "aggs": {
         "f": {
          "filter": {
           "term": {
            "panels.render_status": "empty"
           }
          }
         }
        }
       },
       "error": {
        "nested": {
         "path": "panels"
        },
        "aggs": {
         "f": {
          "filter": {
           "term": {
            "panels.render_status": "error"
           }
          }
         }
        }
       },
       "timeout": {
        "nested": {
         "path": "panels"
        },
        "aggs": {
         "f": {
          "filter": {
           "term": {
            "panels.render_status": "timeout"
           }
          }
         }
        }
       },
       "missing": {
        "nested": {
         "path": "panels"
        },
        "aggs": {
         "f": {
          "filter": {
           "term": {
            "panels.render_status": "missing"
           }
          }
         }
        }
       }
      }
     }
    }
   }
  },
  "format": {
   "property": "aggregations.by_dash.buckets"
  }
 },
 "transform": [
  {
   "calculate": "datum.key",
   "as": "dashboard"
  },
  {
   "calculate": "datum.ok.f.doc_count",
   "as": "ok"
  },
  {
   "calculate": "datum.empty.f.doc_count",
   "as": "empty"
  },
  {
   "calculate": "datum.error.f.doc_count",
   "as": "error"
  },
  {
   "calculate": "datum.timeout.f.doc_count",
   "as": "timeout"
  },
  {
   "calculate": "datum.missing.f.doc_count",
   "as": "missing"
  },
  {
   "fold": [
    "ok",
    "empty",
    "error",
    "timeout",
    "missing"
   ],
   "as": [
    "status",
    "count"
   ]
  },
  {
   "joinaggregate": [
    {
     "op": "sum",
     "field": "count",
     "as": "total"
    }
   ],
   "groupby": [
    "dashboard"
   ]
  },
  {
   "calculate": "datum.total > 0 ? datum.count / datum.total : 0",
   "as": "share"
  }
 ],
 "encoding": {
  "x": {
   "field": "status",
   "type": "ordinal",
   "sort": [
    "ok",
    "empty",
    "error",
    "timeout",
    "missing"
   ],
   "title": null,
   "axis": {
    "orient": "top",
    "labelAngle": 0
   }
  },
  "y": {
   "field": "dashboard",
   "type": "nominal",
   "title": null,
   "axis": {
    "labelLimit": 260
   }
  }
 },
 "layer": [
  {
   "mark": {
    "type": "rect",
    "cornerRadius": 3
   },
   "encoding": {
    "color": {
     "field": "status",
     "type": "nominal",
     "legend": null,
     "scale": {
      "domain": [
       "ok",
       "empty",
       "error",
       "timeout",
       "missing"
      ],
      "range": [
       "#1E9E6A",
       "#D68A00",
       "#D13B34",
       "#D13B34",
       "#8794A6"
      ]
     }
    },
    "opacity": {
     "field": "share",
     "type": "quantitative",
     "legend": null,
     "scale": {
      "domain": [
       0,
       1
      ],
      "range": [
       0.07,
       1
      ]
     }
    },
    "tooltip": [
     {
      "field": "dashboard"
     },
     {
      "field": "status"
     },
     {
      "field": "count",
      "title": "Panel results"
     },
     {
      "field": "share",
      "format": ".1%"
     }
    ]
   }
  },
  {
   "mark": {
    "type": "text",
    "fontSize": 10
   },
   "encoding": {
    "text": {
     "field": "share",
     "type": "quantitative",
     "format": ".0%"
    },
    "color": {
     "condition": {
      "test": "datum.share > 0.6",
      "value": "white"
     },
     "value": "#1A2433"
    }
   }
  }
 ]
}"}}

