{"title": "Load time baseline", "type": "vega", "aggs": [], "params": {"spec": "{
 "$schema": "https://vega.github.io/schema/vega/v5.json",
 "autosize": {
  "type": "fit",
  "contains": "padding"
 },
 "padding": 0,
 "data": [
  {
   "name": "base",
   "url": {
    "%context%": true,
    "%timefield%": "@timestamp",
    "index": "dashboard-health-monitor*",
    "body": {
     "size": 0,
     "aggs": {
      "d": {
       "terms": {
        "field": "dashboard_title",
        "size": 100
       },
       "aggs": {
        "load": {
         "percentiles": {
          "field": "load_time_ms",
          "percents": [
           50,
           95
          ]
         }
        },
        "mx": {
         "max": {
          "field": "load_time_ms"
         }
        },
        "ok": {
         "filter": {
          "term": {
           "load_status": "ok"
          }
         }
        }
       }
      }
     }
    }
   },
   "format": {
    "property": "aggregations.d.buckets"
   },
   "transform": [
    {
     "type": "formula",
     "as": "name",
     "expr": "datum.key"
    },
    {
     "type": "formula",
     "as": "p50",
     "expr": "max(0.1, datum.load.values['50.0'] / 1000)"
    },
    {
     "type": "formula",
     "as": "p95",
     "expr": "max(0.1, datum.load.values['95.0'] / 1000)"
    },
    {
     "type": "formula",
     "as": "mx_s",
     "expr": "max(0.1, datum.mx.value / 1000)"
    },
    {
     "type": "formula",
     "as": "ok_pct",
     "expr": "datum.doc_count > 0 ? datum.ok.doc_count / datum.doc_count : 0"
    },
    {
     "type": "collect",
     "sort": {
      "field": "p95",
      "order": "descending"
     }
    },
    {
     "type": "window",
     "ops": [
      "row_number"
     ],
     "as": [
      "idx"
     ]
    },
    {
     "type": "formula",
     "as": "y",
     "expr": "40 + (datum.idx - 1) * 24"
    }
   ]
  },
  {
   "name": "top",
   "source": "base",
   "transform": [
    {
     "type": "aggregate",
     "fields": [
      "mx_s"
     ],
     "ops": [
      "max"
     ],
     "as": [
      "m"
     ]
    }
   ]
  }
 ],
 "marks": [
  {
   "type": "rect",
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "y": {
      "value": 0
     },
     "width": {
      "signal": "width"
     },
     "height": {
      "value": 28
     },
     "fill": {
      "value": "#F6F8FB"
     },
     "cornerRadius": {
      "value": 4
     }
    }
   }
  },
  {
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "value": 12
     },
     "y": {
      "value": 19
     },
     "text": {
      "value": "Dashboard"
     },
     "fill": {
      "value": "#5A6B80"
     },
     "fontSize": {
      "value": 11
     },
     "fontWeight": {
      "value": "600"
     },
     "align": {
      "value": "left"
     },
     "baseline": {
      "value": "alphabetic"
     }
    }
   }
  },
  {
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "signal": "left"
     },
     "y": {
      "value": 19
     },
     "text": {
      "value": "bar = median to p95 \u00b7 dot = median \u00b7 tick = slowest   (seconds, log scale)"
     },
     "fill": {
      "value": "#5A6B80"
     },
     "fontSize": {
      "value": 11
     },
     "fontWeight": {
      "value": "600"
     },
     "align": {
      "value": "left"
     },
     "baseline": {
      "value": "alphabetic"
     }
    }
   }
  },
  {
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "signal": "width - 8"
     },
     "y": {
      "value": 19
     },
     "text": {
      "value": "median \u00b7 p95 \u00b7 slowest \u00b7 ok %"
     },
     "fill": {
      "value": "#5A6B80"
     },
     "fontSize": {
      "value": 11
     },
     "fontWeight": {
      "value": "600"
     },
     "align": {
      "value": "right"
     },
     "baseline": {
      "value": "alphabetic"
     }
    }
   }
  },
  {
   "type": "rule",
   "encode": {
    "update": {
     "x": {
      "signal": "scale('x', 0.1)"
     },
     "x2": {
      "signal": "scale('x', 0.1)"
     },
     "y": {
      "value": 32
     },
     "y2": {
      "signal": "height - 14"
     },
     "stroke": {
      "value": "#D5DCE6"
     },
     "opacity": {
      "value": 0.8
     }
    }
   }
  },
  {
   "type": "text",
   "encode": {
